def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    projections = (
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r + c,
        lambda r, c: c - r,
    )

    best = None
    for period in range(2, min(15, max(h, w) + 1)):
        for proj in projections:
            mapping = {}
            valid = True
            for r, c, color in cells:
                residue = proj(r, c) % period
                if residue in mapping and mapping[residue] != color:
                    valid = False
                    break
                mapping[residue] = color
            if valid and mapping:
                candidate = (len(mapping), mapping, proj, period)
                if best is None or len(mapping) > best[0]:
                    best = candidate
        if best is not None:
            break

    if best is None:
        return grid

    _, mapping, proj, period = best
    return [
        [mapping[proj(r, c) % period] for c in range(w)]
        for r in range(h)
    ]
